/// Peeks the next lexer token if any, but transposes it for convenience.
fn peek(&mut self) -> Result<Option<&Token>> {
    Ok(self.lexer.peek().map(|r| r.as_ref().ok()?))
}

/// Peeks the next lexer token if any, returning the token directly.
fn peek_token(&mut self) -> Result<Option<&Token>> {
    Ok(self.lexer.peek().and_then(|r| r.as_ref().ok()))
}

